// Helper functions
export function getPricesByCategory(category: string): PriceItem[] {
  return prices.filter(item => item.category === category)
}

export function getPricesByGroup(category: string, group: string): PriceItem[] {
  return prices.filter(item => item.category === category && item.group === group)
}

export function getCategoryBySlug(slug: string): PriceCategory | undefined {
  return priceCategories.find(cat => cat.slug === slug)
}

export function searchPrices(query: string): PriceItem[] {
  const lowerQuery = query.toLowerCase()
  return prices.filter(item => 
    item.name.toLowerCase().includes(lowerQuery) ||
    item.category.toLowerCase().includes(lowerQuery) ||
    (item.group && item.group.toLowerCase().includes(lowerQuery))
  )
}

export function getPriceRange(category: string): { min: number; max: number } {
  const categoryPrices = getPricesByCategory(category)
  if (categoryPrices.length === 0) return { min: 0, max: 0 }
  
  const prices = categoryPrices.map(item => item.price)
  return {
    min: Math.min(...prices),
    max: Math.max(...prices)
  }
}

export function getTotalServiceCount(): number {
  return prices.length
}

export function getCategoryCount(): number {
  return priceCategories.length
}